public class Solution {
    static class Node {
        int val;
        Node esq, dir;
        Node(int val, Node esq, Node dir) { this.val = val; this.esq = esq; this.dir = dir; }
    }

    private static long melhor;

    static long somaMaxima(Node raiz) {
        melhor = Long.MIN_VALUE;
        descer(raiz);
        return melhor;
    }

    // Retorno local: um braço (para o pai). Máximo global: os dois braços passando pelo nó.
    private static long descer(Node n) {
        if (n == null) return 0;
        long e = Math.max(0, descer(n.esq)), d = Math.max(0, descer(n.dir));
        melhor = Math.max(melhor, n.val + e + d);
        return n.val + Math.max(e, d);
    }
}

