import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    private static Solution.Node n(int v, Solution.Node e, Solution.Node d) { return new Solution.Node(v, e, d); }
    private static Solution.Node f(int v) { return new Solution.Node(v, null, null); }

    @Test void exemplos() {
        assertEquals(6, Solution.somaMaxima(n(1, f(2), f(3))));
        assertEquals(42, Solution.somaMaxima(n(-10, f(9), n(20, f(15), f(7)))));
    }

    @Test void todosNegativos() {
        assertEquals(-2, Solution.somaMaxima(n(-3, f(-2), f(-5))));
    }

    @Test void naoPassaPelaRaiz() {
        // o melhor caminho é 4 -> 5 -> 6 dentro da subárvore esquerda
        assertEquals(15, Solution.somaMaxima(n(-100, n(5, f(4), f(6)), f(1))));
    }

    @Test void valoresGrandes() {
        assertEquals(3L * Integer.MAX_VALUE, Solution.somaMaxima(n(Integer.MAX_VALUE, f(Integer.MAX_VALUE), f(Integer.MAX_VALUE))));
    }
}

