import java.util.Arrays;

public class Solution {
    static long tsp(int[][] dist) {
        int n = dist.length;
        if (n == 1) return 0;
        long INF = Long.MAX_VALUE / 4;
        long[][] dp = new long[1 << n][n];
        for (long[] linha : dp) Arrays.fill(linha, INF);
        dp[1][0] = 0;
        for (int m = 1; m < 1 << n; m++) {
            if ((m & 1) == 0) continue; // todo caminho começa em 0
            for (int u = 0; u < n; u++) {
                if (dp[m][u] == INF) continue;
                for (int v = 0; v < n; v++) {
                    if ((m >> v & 1) == 1) continue;
                    int nm = m | 1 << v;
                    dp[nm][v] = Math.min(dp[nm][v], dp[m][u] + dist[u][v]);
                }
            }
        }
        long melhor = INF;
        for (int u = 1; u < n; u++) melhor = Math.min(melhor, dp[(1 << n) - 1][u] + dist[u][0]);
        return melhor;
    }
}

