import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    private static long bruta(int[][] d) {
        int n = d.length;
        List<Integer> resto = new ArrayList<>();
        for (int i = 1; i < n; i++) resto.add(i);
        return permutar(d, resto, 0, 0);
    }

    private static long permutar(int[][] d, List<Integer> resto, int u, long custo) {
        if (resto.isEmpty()) return custo + d[u][0];
        long melhor = Long.MAX_VALUE;
        for (int i = 0; i < resto.size(); i++) {
            int v = resto.remove(i);
            melhor = Math.min(melhor, permutar(d, resto, v, custo + d[u][v]));
            resto.add(i, v);
        }
        return melhor;
    }

    @Test void exemplo() {
        int[][] d = {{0, 10, 15, 20}, {10, 0, 35, 25}, {15, 35, 0, 30}, {20, 25, 30, 0}};
        assertEquals(80, Solution.tsp(d));
        assertEquals(0, Solution.tsp(new int[][]{{0}}));
    }

    @Test void aleatorioContraBruta() {
        var rnd = new Random(13);
        for (int t = 0; t < 30; t++) {
            int n = 2 + rnd.nextInt(6);
            int[][] d = new int[n][n];
            for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) d[i][j] = i == j ? 0 : 1 + rnd.nextInt(100);
            assertEquals(bruta(d), Solution.tsp(d));
        }
    }

    @Test void dezesseisCidades() {
        int n = 16;
        int[][] d = new int[n][n];
        for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) d[i][j] = Math.abs(i - j) * 3;
        assertEquals(2L * 3 * (n - 1), Solution.tsp(d));
    }
}
